files.content:
:root {
  --pixel: 4px;
  --ink: #222;
  --bg: #f0e6d2;
  --accent: #ff6b6b;
  --accent2: #6bc5ff;
  --accent3: #ffe66d;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
}

.counter {
  background: #fff;
  border: var(--pixel) solid var(--ink);
  box-shadow: 8px 8px 0 var(--ink);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  align-items: center;
  max-width: 320px;
  width: 100%;
}

h1 {
  margin: 0;
  font-size: 1.4rem;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0 var(--accent3);
}

#count {
  font-size: 4rem;
  font-weight: bold;
  background: #111;
  color: #0f0;
  padding: 0.5rem 1rem;
  border: var(--pixel) solid var(--ink);
  box-shadow: inset 0 0 0 2px #333, 4px 4px 0 var(--ink);
  min-width: 5ch;
  text-align: center;
  display: block;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}

.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 0.75rem 1rem;
  color: var(--ink);
  background: var(--accent);
  border: var(--pixel) solid var(--ink);
  box-shadow: 4px 4px 0 var(--ink);
  cursor: pointer;
}

.pixel-btn:nth-child(2) { background: var(--accent2); }
.pixel-btn:nth-child(3) { background: var(--accent3); }
.pixel-btn:hover { filter: brightness(1.05); }

.pixel-btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--ink);
}

.pixel-btn:focus-visible {
  outline: 3px dashed #000;
  outline-offset: 3px;
}

const countEl = document.getElementById('count');
let count = 0;

const update = () => {
  countEl.textContent = count;
};

document.getElementById('increase').addEventListener('click', () => {
  count += 1;
  update();
});

document.getElementById('decrease').addEventListener('click', () => {
  count -= 1;
  update();
});

document.getElementById('reset').addEventListener('click', () => {
  count = 0;
  update();
});

update();
